+package net.javacrumbs.jsonunit.assertj;
+
+import org.assertj.core.api.AssertionInfo;
+import org.assertj.core.internal.ComparatorBasedComparisonStrategy;
+import org.assertj.core.internal.Iterables;
+
+class JsonIterables extends Iterables {
+    private static final String ARRAY_LIST_DESCRIPTION = "Expecting ArrayList:";
+    private static final String JSON_LIST_DESCRIPTION = "Expecting JsonList:";
+
+    JsonIterables(JsonComparator comparator) {
+        super(new ComparatorBasedComparisonStrategy(comparator));
+    }
+
+    @Override
+    public void assertContains(AssertionInfo info, Iterable<?> actual, Object[] values) {
+        try {
+            super.assertContains(info, actual, values);
+        } catch (AssertionError e) {
+            throw replaceArrayListDescription(e);
+        }
+    }
+
+    @Override
+    public void assertContainsOnly(AssertionInfo info, Iterable<?> actual, Object[] expectedValues) {
+        try {
+            super.assertContainsOnly(info, actual, expectedValues);
+        } catch (AssertionError e) {
+            throw replaceArrayListDescription(e);
+        }
+    }
+
+    private AssertionError replaceArrayListDescription(AssertionError error) {
+        String message = error.getMessage();
+        if (message == null || !message.contains(ARRAY_LIST_DESCRIPTION)) {
+            return error;
+        }
+
+        AssertionError result = new AssertionError(message.replace(ARRAY_LIST_DESCRIPTION, JSON_LIST_DESCRIPTION));
+        result.setStackTrace(error.getStackTrace());
+        return result;
+    }
+}
